cd /workspace && node -e "
const XLSX = require('xlsx');
const fs = require('fs');

const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const lines = [];

for (const sheetName of wb.SheetNames) {
  const sheet = wb.Sheets[sheetName];
  const range = XLSX.utils.decode_range(sheet['!ref']);
  lines.push('Sheet: ' + sheetName);
  lines.push('Range: ' + sheet['!ref']);
  lines.push('');

  // Header + data as TSV
  const data = XLSX.utils.sheet_to_json(sheet, { header: 1 });
  const header = data[0];
  lines.push(header.join('\t'));
  lines.push('-'.repeat(100));

  for (let i = 1; i < data.length; i++) {
    const row = data[i].map(c => (c === undefined ? '' : c));
    lines.push(row.join('\t'));
  }

  lines.push('');
  lines.push('Total data rows: ' + (data.length - 1));

  // Also dump every individual cell reference
  lines.push('');
  lines.push('=== Individual Cell Contents ===');
  for (let r = range.s.r; r <= range.e.r; r++) {
    for (let c = range.s.c; c <= range.e.c; c++) {
      const addr = XLSX.utils.encode_cell({ r, c });
      const cell = sheet[addr];
      if (cell) {
        lines.push(addr + ' = ' + JSON.stringify(cell.v) + '  (type: ' + cell.t + ')');
      }
    }
  }
}

const output = lines.join('\n');
fs.writeFileSync('order_summary_extracted.txt', output);
console.log('Saved to order_summary_extracted.txt (' + lines.length + ' lines)');
"
